/** Prices every run at its own agent's rate, so one card may mix agents without losing either. */
function groupCost(group: ConversationGroup, rates: Map<string, ProviderRate>): GroupCost {
    const agentIdentities = new Set<string>();
    const unpricedByReason = new Map<string, number>();
    let value = 0;
    for (const { agent, totalTokens } of group.conversations) {
        agentIdentities.add(agent ?? UNKNOWN_AGENT_LABEL);
        const rate = agent === null ? undefined : rates.get(agent);
        if (rate?.available) {
            value += totalTokens / rate.tokensPerDollar;
            continue;
        }
        const reason = rate?.reason ?? NO_ACCOUNT_SERIES_REASON;
        unpricedByReason.set(reason, (unpricedByReason.get(reason) ?? 0) + 1);
    }
    const singleAgent = agentIdentities.size === 1 ? [...agentIdentities][0] : null;

    return {
        priced: group.conversations.length > [...unpricedByReason.values()].reduce((total, count) => total + count, 0),
        rate: singleAgent ? rates.get(singleAgent) ?? null : null,
        singleAgent,
        unpricedByReason,
        value,
    };
}

function costRow(
    controls: StatsControls,
    groupIdentity: string,
    group: ConversationGroup,
    rates: Map<string, ProviderRate>,
): StatsChartRow {
    const { priced, rate, singleAgent, unpricedByReason, value } = groupCost(group, rates);
    const extraLines: StatsTooltipLine[] = [{
        label: 'Priced with',
        value: singleAgent ? `${singleAgent} subscription rate` : 'Mixed agents',
    }];
    for (const [reason, count] of unpricedByReason) {
        extraLines.push({ label: null, value: `Not priced: ${count} run${count === 1 ? '' : 's'} (${reason})` });
    }
    const row = totalRow(controls, groupIdentity, { label: group.label, title: group.title, value }, 'dollars', extraLines);

    return {
        ...row,
        agent: singleAgent,
        available: priced,
        denominator: rate?.denominator ?? null,
        limitId: rate?.limitId ?? null,
        numerator: rate?.numerator ?? null,
        provider: singleAgent,
        sampleCount: group.conversations.length,
        seriesIdentity: singleAgent ?? MIXED_AGENT_IDENTITY,
        seriesLabel: singleAgent ?? 'Mixed',
        windowId: rate?.windowId ?? null,
    };
}

function costTotalsRows(source: LoadedStatsSource, controls: StatsControls, conversations: StatsConversationFact[]) {
    const rates = providerRates(source, controls);

    return [...conversationGroups(source, controls, conversations)]
        .map(([groupIdentity, group]) => costRow(controls, groupIdentity, group, rates));
}

/** One bar per card or action; cost prices every run at the rate of the agent that ran it. */
export function totalsRows(source: LoadedStatsSource, controls: StatsControls): StatsChartRow[] {
    const conversations = source.stats.conversations.filter((fact) => isCountedConversation(fact, controls));
    const rows = controls.totalsMetric === 'cost'
        ? costTotalsRows(source, controls, conversations)
        : basicTotalsRows(source, controls, conversations);

    return rows.sort((left, right) => right.value - left.value || left.displayLabel.localeCompare(right.displayLabel));
}

import {
    TERMINAL_CONVERSATION_STATUSES,
    type LoadedStatsSource,
    type ProjectStatsSnapshot,
    type StatsChartRow,
    type StatsControls,
    type StatsOptions,
} from './project_stats_types';
import { activityRows } from './stats_activity_dataset';
import { buildOptions, reconcileControls } from './stats_options';
import { eligibleSamples, performanceRows, type EligibleSample } from './stats_performance_dataset';
import { inRange } from './stats_time_buckets';
import { totalsRows } from './stats_totals_dataset';
import { usageComparisonRows } from './stats_usage_comparison_dataset';

function datasetRows(
    source: LoadedStatsSource,
    controls: StatsControls,
    options: StatsOptions,
    samples: EligibleSample[],
): StatsChartRow[] {
    if (controls.dataset === 'activityOverTime') return activityRows(source, controls, controls.activityGranularity);
    if (controls.dataset === 'agentPerformance') return performanceRows(controls, samples);
    if (controls.dataset === 'usageComparison') return usageComparisonRows(source, controls, options);

    return totalsRows(source, controls);
}

function omittedTimerCount(source: LoadedStatsSource, controls: StatsControls) {
    return source.stats.conversations.filter((conversation) => (
        TERMINAL_CONVERSATION_STATUSES.has(conversation.status)
        && conversation.completedAt !== null
        && inRange(conversation.completedAt, controls)
        && conversation.elapsedMs === null
    )).length;
}

/** Reconciles controls against the loaded source, then aggregates the selected dataset once. */
export function buildSnapshot(source: LoadedStatsSource, requestedControls: StatsControls): ProjectStatsSnapshot {
    const options = buildOptions(source);
    const controls = reconcileControls(requestedControls, options);
    const performance = eligibleSamples(source, controls);
    const rows = datasetRows(source, controls, options, performance.samples);
    const excludedSampleCount = Object.values(performance.exclusionCounts).reduce((total, count) => total + count, 0);

    return {
        controls,
        error: null,
        excludedSampleCount,
        exclusionCounts: performance.exclusionCounts,
        omittedTimerCount: omittedTimerCount(source, controls),
        options,
        rows,
        status: 'ready',
        tokenTimeAvailable: source.tokenTimeAvailable,
        warnings: source.warnings,
    };
}

